  'rsv.lost': 'perdidas {n}', 'rsv.mob': 'saltos {n}', 'rsv.mobT': 'Saltos possíveis agora (nenhum na sua vez = derrota)', 'rsv.title': '{c}: {a} pedras perdidas · {b} saltos',
